'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // rejection not cached; shared reason; retry
  { let n = 0; const reason = { x: 1 };
    const c = createCache({ now: () => 0, load() { n++; if (n === 1) throw reason; return 'ok'; } });
    const [a, b] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(a.reason, reason); assert.equal(b.reason, reason); assert.equal(n, 1);
    assert.equal(await c.get('k'), 'ok'); assert.equal(n, 2); }
  // set wins over pending load, TTL not restarted, expiry starts fresh load
  { let t = 0, n = 0; const g = deferred();
    const c = createCache({ now: () => t, ttlMs: 10, load() { n++; return n === 1 ? g.promise : 'new'; } });
    const r = c.get('k'); await tick();
    c.set('k', 'set'); t = 5; g.resolve('old');
    assert.equal(await r, 'old'); assert.equal(await c.get('k'), 'set');
    t = 10; assert.equal(c.size, 0); assert.equal(await c.get('k'), 'new'); assert.equal(n, 2); }
  // old flight finishing does not detach/clobber newer flight; repeated invalidations
  { let n = 0; const gs = [deferred(), deferred(), deferred()];
    const c = createCache({ now: () => 0, load() { return gs[n++].promise; } });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.invalidate('k');
    const d = c.get('k'); await tick();
    gs[0].resolve('A'); gs[1].resolve('B'); assert.equal(await a, 'A'); assert.equal(await b, 'B');
    const d2 = c.get('k'); assert.equal(n, 3); assert.equal(c.size, 0);
    gs[2].resolve('C'); assert.equal(await d, 'C'); assert.equal(await d2, 'C');
    assert.equal(await c.get('k'), 'C'); assert.equal(n, 3); }
  // detached rejected flight does not remove newer flight
  { let n = 0; const gs = [deferred(), deferred()];
    const c = createCache({ now: () => 0, load() { return gs[n++].promise; } });
    const a = c.get('k'); await tick(); c.clear();
    const b = c.get('k'); await tick();
    gs[0].reject('boom'); await assert.rejects(a, x => x === 'boom');
    const b2 = c.get('k'); assert.equal(n, 2);
    gs[1].resolve('B'); assert.equal(await b, 'B'); assert.equal(await b2, 'B'); }
  // load invalidates own key synchronously, and joins own flight
  { let n = 0, inner;
    const c = createCache({ now: () => 0, load(k) { n++; if (n === 1) { inner = c.get(k); c.invalidate(k); } return 'v' + n; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(await inner, 'v1'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(n, 2); }
  // ttl 0 dedups but never reuses
  { let n = 0; const c = createCache({ now: () => 0, ttlMs: 0, load() { n++; return n; } });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]); assert.equal(x, 1); assert.equal(y, 1);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0); }
  console.log('all ok');
})().catch(e => { console.error(e); process.exit(1); });

'use strict';
function createFlights() {
  const pending = new Map();
  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      const promise = Promise.resolve().then(work).then(value => {
        pending.delete(key);
        commit(value);
        return value;
      });
      pending.set(key, promise);
      return promise;
    },
    forget(key) { pending.delete(key); },
    clear() { pending.clear(); }
  };
}
module.exports = { createFlights };

